import asyncio
import websockets
import json
import subprocess
import os
import re
import hashlib
import hmac
from urllib.parse import urlparse, unquote

# Kubernetes pod health check WebSocket server
# Handles internal service mesh communication for pod diagnostics

SERVICE_SECRET = os.environ.get('SERVICE_SECRET', 'k8s-internal-mesh-secret')
ALLOWED_NAMESPACES = ['default', 'monitoring', 'kube-system']
ALLOWED_COMMANDS = frozenset(['ping', 'traceroute', 'dig', 'nslookup', 'curl'])

class PodDiagnosticHandler:
    def __init__(self):
        self.session_registry = {}
        self.command_history = []
        self._sanitizer_cache = {}

    def verify_mesh_token(self, token, namespace):
        """Verify service mesh authentication token"""
        expected = hmac.new(
            SERVICE_SECRET.encode(),
            namespace.encode(),
            hashlib.sha256
        ) if hasattr(hmac, 'new') else hmac.HMAC(
            SERVICE_SECRET.encode(),
            namespace.encode(),
            hashlib.sha256
        )
        return hmac.compare_digest(expected.hexdigest(), token)

    def sanitize_target(self, target):
        """Sanitize diagnostic target - allow hostnames, IPs, and service names"""
        # Remove any null bytes
        target = target.replace('\x00', '')
        # Block obvious shell metacharacters
        blocked_chars = set(';&|`$\\\n\r')
        if any(c in blocked_chars for c in target):
            return None
        # Validate format: hostname, IP, or k8s service name
        pattern = r'^[a-zA-Z0-9][a-zA-Z0-9._\-:/]+[a-zA-Z0-9/]$'
        if not re.match(pattern, target):
            return None
        return target

    def build_command(self, tool, target, options=None):
        """Build diagnostic command with validated components"""
        if tool not in ALLOWED_COMMANDS:
            return None

        sanitized_target = self.sanitize_target(target)
        if sanitized_target is None:
            return None

        # Build base command
        cmd_parts = [tool]

        # Apply tool-specific safe options
        if tool == 'ping':
            cmd_parts.extend(['-c', '3', '-W', '2'])
        elif tool == 'traceroute':
            cmd_parts.extend(['-m', '15', '-w', '2'])
        elif tool == 'dig':
            cmd_parts.extend(['+short', '+time=3'])
        elif tool == 'curl':
            cmd_parts.extend(['-s', '-m', '5', '-o', '/dev/null', '-w', '%{http_code}'])

        cmd_parts.append(sanitized_target)
        return cmd_parts

    def resolve_service_endpoint(self, service_ref):
        """Resolve Kubernetes service reference to endpoint
        Format: namespace/service-name:port or service-name.namespace.svc.cluster.local
        """
        # Handle URL-encoded service references from mesh proxy
        decoded_ref = unquote(service_ref)
        # Handle k8s service DNS format
        if '.svc.cluster.local' in decoded_ref:
            return decoded_ref
        # Handle namespace/service:port format
        if '/' in decoded_ref:
            parts = decoded_ref.split('/')
            namespace = parts[0]
            if namespace not in ALLOWED_NAMESPACES:
                return None
            service_part = '/'.join(parts[1:])
            return f"{service_part}.{namespace}.svc.cluster.local"
        return decoded_ref

    async def execute_diagnostic(self, tool, target, use_shell=False):
        """Execute diagnostic command and return output"""
        cmd_parts = self.build_command(tool, target)
        if cmd_parts is None:
            return {"error": "Invalid command or target"}

        try:
            # Use shell=False for security with pre-built argument list
            if use_shell:
                # Legacy mode for complex service mesh routing
                cmd_string = ' '.join(cmd_parts)
                proc = await asyncio.create_subprocess_shell(
                    cmd_string,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE
                )
            else:
                proc = await asyncio.create_subprocess_exec(
                    *cmd_parts,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.PIPE
                )
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=10)
            return {
                "stdout": stdout.decode('utf-8', errors='replace')[:4096],
                "stderr": stderr.decode('utf-8', errors='replace')[:1024],
                "returncode": proc.returncode
            }
        except asyncio.TimeoutError:
            return {"error": "Command timed out"}
        except Exception as e:
            return {"error": f"Execution failed: {type(e).__name__}"}

    async def handle_message(self, websocket, message):
        """Process incoming diagnostic request"""
        try:
            data = json.loads(message)
        except json.JSONDecodeError:
            await websocket.send(json.dumps({"error": "Invalid JSON"}))
            return

        action = data.get('action')

        if action == 'authenticate':
            token = data.get('token', '')
            namespace = data.get('namespace', 'default')
            if namespace in ALLOWED_NAMESPACES and self.verify_mesh_token(token, namespace):
                self.session_registry[id(websocket)] = {
                    'authenticated': True,
                    'namespace': namespace
                }
                await websocket.send(json.dumps({"status": "authenticated"}))
            else:
                await websocket.send(json.dumps({"error": "Authentication failed"}))
            return

        # Check authentication
        session = self.session_registry.get(id(websocket))
        if not session or not session.get('authenticated'):
            await websocket.send(json.dumps({"error": "Not authenticated"}))
            return

        if action == 'diagnose':
            tool = data.get('tool', 'ping')
            raw_target = data.get('target', '')

            # Resolve service reference if it looks like a k8s reference
            if '/' in raw_target or '.svc.' in raw_target or '%' in raw_target:
                target = self.resolve_service_endpoint(raw_target)
            else:
                target = raw_target

            if target is None:
                await websocket.send(json.dumps({"error": "Invalid service reference"}))
                return

            # Determine execution mode based on target complexity
            # Service mesh targets with special routing need shell for pipe support
            needs_shell = data.get('mesh_routing', False) and session['namespace'] == 'kube-system'

            result = await self.execute_diagnostic(tool, target, use_shell=needs_shell)
            self.command_history.append({
                'tool': tool,
                'target': target,
                'namespace': session['namespace']
            })
            await websocket.send(json.dumps(result))

        elif action == 'status':
            await websocket.send(json.dumps({
                "pod": os.environ.get('POD_NAME', 'unknown'),
                "namespace": session['namespace'],
                "commands_executed": len(self.command_history)
            }))


handler = PodDiagnosticHandler()

async def ws_handler(websocket, path):
    try:
        async for message in websocket:
            await handler.handle_message(websocket, message)
    finally:
        handler.session_registry.pop(id(websocket), None)


if __name__ == '__main__':
    port = int(os.environ.get('WS_PORT', '8765'))
    start_server = websockets.serve(ws_handler, '0.0.0.0', port)
    print(f"Pod diagnostic WebSocket server starting on port {port}")
    asyncio.get_event_loop().run_until_complete(start_server)
    asyncio.get_event_loop().run_forever()
